"""Add explicitly named home variants with original instructions; preserve IDs."""
import json
from pathlib import Path
library=json.loads(Path('lib/exercise-library.json').read_text())
guides=json.loads(Path('public/exercise-guides.json').read_text())
media=json.loads(Path('public/exercise-content.json').read_text())
variants=[
 dict(id='lib-single-db-rdl',name='Two-hand single-dumbbell Romanian deadlift',role='Hinge',muscles=['hamstrings','glutes'],base='rdl',eq='Dumbbell',multiplier=1,convention='One dumbbell held in both hands; enter its total weight and total repetitions.',equipment=['One dumbbell with a secure two-hand grip','Clear standing space'],setup=['Stand with feet about hip-width apart and a small bend in your knees.','Hold one dumbbell securely with both hands in front of your thighs. Choose a shape you can grip without pinching fingers.'],execution=['Move your hips back as the dumbbell travels close to your legs. Keep the knee bend fairly steady.','Lower only as far as you can keep your trunk controlled; reaching the floor is not the target.','Push through your feet and bring your hips forward to stand. Finish upright without leaning backward.'],finish=['Set the dumbbell down with a controlled hip and knee bend.'],errors=['Bending deeper at the knees turns this into a squat rather than a hip hinge.','Reaching farther by rounding or yanking the weight does not improve the set.'],easier='Practice the hip-back motion without weight, or shorten the lowering range.',safety='Use a weight and grip you can control. Stop for pain, dizziness or a slipping grip; seek instruction if this hinge is unfamiliar.'),
 dict(id='lib-band-standing-row',name='Standing anchored resistance-band row',role='Pull',muscles=['upper back','lats','elbow flexors'],base='band-row',eq='Resistance band',multiplier=0,convention='Record band identity, anchor height and starting distance; total simultaneous repetitions. Do not invent a kilogram value.',equipment=['Undamaged resistance band','Anchor designed and rated for band exercise'],setup=['Secure the band to its intended anchor around lower-chest height, following the manufacturer’s instructions.','Face the anchor in a balanced stance. Start with arms reaching forward and light band tension.'],execution=['Pull your elbows back toward your sides while keeping your trunk steady.','Pause briefly without forcing your shoulders backward or leaning away from the anchor.','Let the arms reach forward under control. Repeat with the same stance and distance.'],finish=['Walk toward the anchor to remove tension before putting the band down.'],errors=['Leaning backward uses body movement to replace the pulling work.','An unsecured door handle or household object can release suddenly.'],easier='Use a lighter band or stand closer while keeping some starting tension.',safety='Check the band and anchor before each set. Keep the recoil path away from your face; do not use a damaged band or improvised anchor.'),
 dict(id='lib-single-db-curl',name='Standing one-arm dumbbell curl',role='Arm',muscles=['elbow flexors'],base='curl',eq='Dumbbell',multiplier=2,convention='One dumbbell; repetitions per side. Do both sides before Done; enter the weight once and the per-side rep count once.',equipment=['One dumbbell','Clear standing space'],setup=['Stand with feet steady and hold the dumbbell at one side, palm facing forward.','Let your free hand rest comfortably. Keep the working upper arm near your side.'],execution=['Bend the elbow to bring the dumbbell up without swinging or lifting the shoulder.','Lower until your elbow is comfortably straight.','Repeat the listed count, then change hands and complete the same count on the other side.'],finish=['Put the dumbbell down under control after both sides. If your sides differ, log them separately rather than inventing equal work.'],errors=['Swinging the trunk makes the repetitions harder to compare.','Counting left plus right as one side’s repetitions doubles the recorded work.'],easier='Use a lighter dumbbell, or choose fewer controlled repetitions and record the actual count.',safety='Keep wrists comfortable. Stop for pain or a slipping grip; never force the elbow past a comfortable range.'),
 dict(id='lib-single-db-floor-press',name='One-arm dumbbell floor press',role='Push',muscles=['chest','triceps'],base='lib-db-floor-press',eq='Dumbbell',multiplier=2,convention='One dumbbell; repetitions per side. Complete both sides before Done and enter its weight and the per-side count once.',equipment=['One manageable dumbbell','Comfortable floor space'],setup=['Sit on the floor with the dumbbell close to your body and carefully lower onto your back. Use help for setup if needed.','Bend your knees with feet grounded. Hold the dumbbell over one side of your chest with the wrist above the elbow.'],execution=['Lower the upper arm until it rests gently on the floor; keep the elbow at a comfortable angle from your torso.','Press upward smoothly without twisting or letting the weight drift toward your face.','Finish the listed count, put the dumbbell down safely, then set up the other side and do the same count.'],finish=['Put the weight down before sitting up; use a controlled floor transfer.'],errors=['Bouncing the arm off the floor loses control.','Twisting the torso or reaching behind the head changes the exercise and can compromise control.'],easier='Use a lighter dumbbell or choose an incline push-up on a secure support.',safety='The floor limits pressing range. Choose a weight you can start and finish safely without dropping it. Use a standing press option if floor transfers are difficult.'),
 dict(id='lib-single-db-split-squat',name='Single-dumbbell static split squat',role='Single leg',muscles=['quadriceps','glutes'],base='lib-db-split-squat',eq='Dumbbell',multiplier=2,convention='One dumbbell total; repetitions per side. Do both sides before Done; enter the single weight and per-side rep count once.',equipment=['One dumbbell','Clear standing space','Optional secure hand support'],setup=['Hold one dumbbell at your chest with both hands, or in one hand by your side. Record the grip you use.','Take a balanced split stance with one foot forward and one back. Keep feet on separate tracks rather than a tightrope.'],execution=['Bend both knees to lower through a comfortable range while keeping the front foot supported.','Stand by pressing through your feet without changing the foot positions.','Finish the listed count and switch the front leg. Complete the same count on both sides.'],finish=['Stand fully and bring your feet together before setting the weight down.'],errors=['A very narrow stance can make balance the limiting factor.','Bouncing at the bottom or pushing the range beyond control does not improve the set.'],easier='Leave the weight out and use a secure support with one hand. Record support and depth so later sets are comparable.',safety='Choose a stable stance and support. A heavier dumbbell is useful only when balance and range remain controlled.'),
 dict(id='lib-band-curl',name='Standing resistance-band curl',role='Arm',muscles=['elbow flexors'],base='curl',eq='Resistance band',multiplier=0,convention='Total simultaneous repetitions; record band identity, grip and stance. Do not enter estimated band weight.',equipment=['Undamaged resistance band designed for standing exercises','Suitable shoes and clear space'],setup=['Following the band manufacturer’s instructions, stand on the middle of the band and hold the ends or handles.','Begin with arms by your sides and palms forward, with light tension and a secure grip.'],execution=['Bend the elbows without swinging your body or moving the upper arms forward.','Lower under control until the elbows are comfortably straight.','Keep foot placement and grip the same for every repetition.'],finish=['Remove tension before releasing the handles or stepping off the band.'],errors=['Changing grip length during the set changes the resistance.','Letting a band slip from underfoot or releasing a stretched handle can cause recoil.'],easier='Use a lighter band or a longer working length within its safe stretch limit.',safety='Check for damage and follow the band’s stretch limit. Keep the recoil path away from your face. Stop if the band slips, hurts or loses its secure grip.')
]
for v in variants:
 tracked=v['eq']=='Dumbbell'
 e=dict(id=v['id'],name=v['name'],pattern=v['role'],equipment=v['eq'],metric='reps',cues=v['execution'],source=guides[v['base']]['sourceURLs'][0],loadConvention=v['convention'],loadMultiplier=v['multiplier'],loadTracked=tracked,requiresSetup=not tracked,primaryMuscles=v['muscles'],instructionStatus='authored-variation',progressionEnabled=tracked,category='Home strength')
 if any(x['id']==e['id'] for x in library):continue
 library.append(e)
 guides[e['id']]=dict(variant=v['name'],summary=v['name']+' uses the equipment listed below. Follow the setup, complete the controlled movement and log the actual work.',equipment=v['equipment'],setup=v['setup'],execution=v['execution'],finish=v['finish'],breathing=['Breathe out during the harder part and in as you return. Keep breathing; avoid a long breath hold.'],commonErrors=v['errors'],easierOption=v['easier'],safety=v['safety'],loadConvention=v['convention'],sourceURLs=guides[v['base']]['sourceURLs'],sourceNote='Original app instructions for this explicitly named variation. Linked sources describe the parent movement or general technique; they are not a verified video of this exact variation. The app cannot assess your form.',quickCues=v['execution'][:3],terms=[{'term':'Per side','meaning':'Complete the stated repetitions with each side; record that count once when both sides are done.'}])
 media[e['id']]=dict(sourceUrl=guides[e['id']]['sourceURLs'][0],hasVideo=False,referenceScope='parent movement or general technique; exact variation video not verified')
for key,label in {'core-hanging-knee-raise':'Pull-up bar','core-hanging-leg-raise':'Pull-up bar','core-captain-chair-knee-raise':'Vertical knee-raise station','core-captain-chair-leg-raise':'Vertical knee-raise station','core-kneeling-ab-wheel':'Ab wheel','core-stability-ball-crunch':'Stability ball'}.items():
 next(x for x in library if x['id']==key)['equipment']=label
terms={'adduction':'Moving a limb toward the middle of your body.','abduction':'Moving a limb away from the middle of your body.','isometric':'Holding a position while the muscles work, rather than moving through repetitions.'}
import re
for g in guides.values():
 text=' '.join([g.get('summary','')]+g.get('setup',[])+g.get('execution',[])+g.get('commonErrors',[]))
 for term,meaning in terms.items():
  if re.search(r'\b'+term+r'\b',text,re.I) and term not in [x['term'].lower() for x in g.get('terms',[])]:g.setdefault('terms',[]).append(dict(term=term,meaning=meaning))
for file,value in [('lib/exercise-library.json',library),('public/exercise-guides.json',guides),('public/exercise-content.json',media)]:Path(file).write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
print('Added six explicit home variants; retained existing IDs, load conventions and source photos.')
